defmodule VoelgoedAi.MixProject do
  use Mix.Project

  # VGAS-000 candidate baseline (2026-11-25).
  # Resolve, audit and compile before treating this as the accepted lockfile.
  # Preserve any necessary configuration/aliases generated by Igniter.
  def project do
    [
      app: :voelgoed_ai,
      version: "0.1.0",
      elixir: "~> 1.20.5",
      elixirc_paths: elixirc_paths(Mix.env()),
      start_permanent: Mix.env() == :prod,
      compilers: [:phoenix_live_view] ++ Mix.compilers(),
      aliases: aliases(),
      deps: deps()
    ]
  end

  def application do
    [
      mod: {VoelgoedAi.Application, []},
      extra_applications: [:logger, :runtime_tools, :crypto]
    ]
  end

  defp elixirc_paths(:test), do: ["lib", "test/support"]
  defp elixirc_paths(_), do: ["lib"]

  defp deps do
    [
      # 01 — Ash domain and persistence foundation
      {:ash, "~> 3.38.1"},
      {:ash_postgres, "~> 2.15.2"},
      {:ash_phoenix, "~> 2.3.26"},
      {:ash_state_machine, "~> 0.3.1"},

      # 02 — Staff identity and authorization (Entra OIDC)
      {:ash_authentication, "== 5.0.0-rc.18"},
      {:ash_authentication_phoenix, "== 3.0.0-rc.12"},

      # 03 — AI and external integrations
      {:ash_ai, "~> 1.5.6"},
      {:req_llm, "~> 1.31.0"},
      {:req, "~> 0.5"},

      # 04 — Durable jobs and asynchronous vectorization
      {:ash_oban, "~> 0.10.3"},
      {:oban, "~> 2.24"},

      # 05 — PostgreSQL and vector support
      {:phoenix_ecto, "~> 4.6"},
      {:ecto_sql, "~> 3.13"},
      {:postgrex, "~> 0.21"},
      {:pgvector, "~> 0.4"},

      # 06 — Phoenix web and LiveView
      {:phoenix, "~> 1.8.17"},
      {:phoenix_html, "~> 4.1"},
      {:phoenix_live_view, "~> 1.2.15"},
      {:bandit, "~> 1.5"},
      {:gettext, "~> 0.26 or ~> 1.0"},
      {:jason, "~> 1.4"},
      {:dns_cluster, "~> 0.2.0"},

      # 07 — Telemetry
      {:telemetry_metrics, "~> 1.0"},
      {:telemetry_poller, "~> 1.0"},

      # 08 — Standard Phoenix assets
      {:esbuild, "~> 0.10", runtime: Mix.env() == :dev},
      {:tailwind, "~> 0.3", runtime: Mix.env() == :dev},
      {:heroicons,
       github: "tailwindlabs/heroicons",
       tag: "v2.2.0",
       sparse: "optimized",
       app: false,
       compile: false,
       depth: 1},

      # 09 — Development and deterministic tests
      {:igniter, "~> 0.8", only: [:dev, :test], runtime: false},
      {:phoenix_live_reload, "~> 1.2", only: :dev},
      {:lazy_html, ">= 0.1.0 and < 1.0.0", only: :test}
    ]
  end

  defp aliases do
    [
      setup: ["deps.get --check-locked", "ecto.migrate"],
      test: ["ecto.migrate --quiet", "test"]
    ]
  end
end
